from pathlib import Path
import json, hashlib, html, copy, re

ROOT=Path.cwd().resolve().parents[1]
REPO=ROOT/'work/americaspeoples'
ARCHIVE=ROOT/'work/intake-2026-10-29-round6'
def read(p): return json.loads(p.read_text(encoding='utf-8'))
def write(p,d): p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
pkg=read(REPO/'data/research-proposals.json')
old=[*read(REPO/'data/evidence.json')['records'],*[p['record'] for p in pkg['proposals']]]
byid={r['id']:r for r in old}
records=[]; updates=[]; sources={}
def source(key,authors,title,year,doi,url=None,access='Primary publisher abstract inspected; full methods not independently audited.',venue='See linked primary publication'):
 s=dict(id='r6-'+key,authors=authors,title=title,year=year,venue=venue,url=url or 'https://doi.org/'+doi,access=access,referenceType='journal-article')
 if doi:s['doi']=doi
 sources[key]=s;return s
def existing(key,record,doi):
 s=copy.deepcopy(next(s for s in byid[record]['sources'] if s.get('doi')==doi));sources[key]=s;return s
def unplaced(original):return dict(kind='unplaced',start=None,end=None,original=original,method='Reported chronology retained without unsupported conversion',interpretation='No justified closed calendar interval was extracted; this context remains in the evidence index.')
def dates(a,b,original,kind='occurrence'):
 return dict(kind=kind,start=a,end=b,approximate=True,original=original,method='Published calendar interval; calibrated BP uses the AD 1950 epoch where explicitly stated.',interpretation='An uncertain occurrence/onset envelope unless explicitly described as an interval; not proof of continuous settlement or an abandonment date.')
def bp(older,younger,original=None,kind='occurrence'):return dates(1950-older,1950-younger,original or f'{older}–{younger} cal BP (AD 1950 epoch)',kind)
def add(key,title,text,s,time,place,limitations,kind=None,status='well-supported',related=()):
 name,lon,lat=place
 precision='Approximate named locality/island reference, rounded for public display; not an excavation coordinate or surveyed boundary.'
 r=dict(id='r6-'+key,revision=1,type='event' if kind else 'occurrence',title=title,culture=dict(id='unknown',name='Unknown attribution',kind='unknown',color='#9babb5'),location=dict(id='r6-'+key+'-place',name=name,lon=lon,lat=lat,precision=precision,provenance='Named geographic setting in the cited study; editorial approximate placement.'),destination=None,routeKind='schematic',time=time,claims=[dict(id='finding',text=text,status=status,explanation=limitations,support=[dict(sourceId=s['id'],stance='supports',locator='Abstract/results as specified in source access',note='Source supports this scoped finding; access and interpretation limits retained.')])],sources=[s],review=dict(summary=text,limitations=limitations,discussion='Population unknown. Site extent, ancestry, archaeological culture, language and present-day identity are distinct. Approximate placement is not exact site mapping.',provenance='2026-10-29 round6 author-supplied syntheses reconciled against linked research; complete intake: docs/intake/index.html.',reviewedAt='2026-10-29',history=['2026-10-29: reconciled for v0.3.6.'],relatedIds=list(related)))
 if kind:
  r['overlay']=dict(kind=kind,basis='schematic',geometry=dict(type='Point',coordinates=[lon,lat]),precision=precision,provenance='Illustrative geographic context only; no precise route or boundary inferred.')
  r['location']=None
 records.append(r);return r
def claim(r,key,text,s,limits,status='under discussion',stance='supports'):
 if not any(x['id']==s['id'] for x in r['sources']):r['sources'].append(s)
 r['claims'].append(dict(id=key,text=text,status=status,explanation=limits,support=[dict(sourceId=s['id'],stance=stance,locator='Source abstract/results',note=limits)]))
def update(target,key,text,s,limits,status='under discussion'):
 r=byid[target]; c=dict(id=key,text=text,status=status,explanation=limits,support=[])
 updates.append(dict(recordId=target,claimId=key,newClaim=c,source=s,stance='context',locator='Round6 source reconciliation',note=limits))

