def narrative(s):
 s=re.sub(r'([A-Za-z])(?=\d)',r'\1 ',s)
 s=re.sub(r'(\d)(?=(?:cal|years|year|thousand|million|m\b|mm\b|BP\b|CE\b|BCE\b|BC\b|AD\b))',r'\1 ',s)
 s=re.sub(r'(\d)(?=[A-Z])',r'\1 ',s)
 s=s.replace('29thcentury','29th century')
 return s
